/* Existing cross-chat artwork and opening film, integrated without altering game state. */
const ExoVisuals=(()=>{
 const root='assets/visual-v13/';
 const beats=[
  {at:0,tag:'01 / ORBITAL WAR',line:'轨道战火之后，中继环只剩残骸。'},
  {at:3,tag:'02 / EMERGENCY LANDING',line:'ECHO–9。你迫降在一片陌生的玄武岩荒原。'},
  {at:6,tag:'03 / SURFACE THREAT',line:'机械猎脊兽正在集结，切断了求救信号。'},
  {at:9,tag:'04 / EXO PROTOCOL',line:'握紧操纵杆。从每一次试射中学习，让下一发更准。'}
 ];let movie=null,active=false,done=null,lastBeat=-1;
 function stop(){active=false;if(movie){movie.onended=movie.ontimeupdate=movie.onerror=movie.onplay=movie.onpause=null;movie.pause?.();movie.removeAttribute?.('src');movie.load?.();movie=null}done=null;lastBeat=-1}
 function finish(){if(!active)return;const next=done;stop();next?.()}
 function sync(){if(!movie)return;const at=Number(movie.currentTime)||0;let i=0;for(let k=0;k<beats.length;k++)if(at>=beats[k].at)i=k;if(i!==lastBeat){lastBeat=i;document.getElementById('exo-film-tag').textContent=beats[i].tag;document.getElementById('exo-film-line').textContent=beats[i].line}const bar=document.getElementById('exo-film-progress');if(bar)bar.style.width=Math.min(100,at/15*100)+'%';const play=document.getElementById('exo-film-play');if(play)play.textContent=movie.paused?'播放':'暂停'}
 function play(){if(!movie)return;const current=movie;try{const pending=current.play();pending?.catch?.(()=>{if(movie!==current)return;const status=document.getElementById('exo-film-status');if(status)status.textContent='点击“播放”开始短片，也可以直接开始驾驶。'})}catch{const status=document.getElementById('exo-film-status');if(status)status.textContent='点击视频控件播放，或直接开始驾驶。'}sync()}
 function toggle(){if(!movie)return;if(movie.paused)play();else{movie.pause();sync()}}
 function audio(){if(!movie)return;movie.muted=!movie.muted;document.getElementById('exo-film-audio').textContent=movie.muted?'开启声音':'关闭声音'}
 function begin(next,reduced=false){stop();active=true;done=next;document.getElementById('app').innerHTML=`<main class="exo"><section class="exo-film"><video id="exo-film" src="${root}opening-15s.mp4" poster="${root}orbital-ring.webp" preload="metadata" playsinline controls muted aria-label="远星协议开场短片：轨道残骸、外星荒原、机械猎脊兽与机甲驾驶舱"></video><div class="exo-film-top"><span>EXO / 远星协议</span><div><button id="exo-film-audio" onclick="ExoVisuals.audio()">开启声音</button><button onclick="ExoVisuals.finish()">跳过，开始驾驶 →</button></div></div><div class="exo-film-copy"><span class="exo-tag" id="exo-film-tag"></span><p id="exo-film-line"></p><div><button id="exo-film-play" onclick="ExoVisuals.toggle()">播放</button><button onclick="Exo.story()">阅读四幕序章</button></div><small id="exo-film-status" role="status"></small></div><div class="exo-film-timeline"><i id="exo-film-progress"></i></div></section></main>`;movie=document.getElementById('exo-film');movie.muted=true;movie.onended=finish;movie.ontimeupdate=sync;movie.onplay=sync;movie.onpause=sync;movie.onerror=()=>{document.getElementById('exo-film-status').textContent='短片暂时无法加载。可以阅读序章，或直接开始驾驶。'};sync();if(!reduced)play()}
 function cockpit(){return `<div class="exo-cockpit-art" aria-hidden="true"><img src="${root}cockpit-frame.webp" alt=""><div class="cockpit-screen cockpit-screen-left"></div><div class="cockpit-screen cockpit-screen-right"></div></div><div class="cockpit-caption">EV–04 AEGIS / 驾驶视野</div><div class="cockpit-record"><span>驾驶记录</span><b id="cockpit-record-value">等待射击</b><small id="cockpit-record-detail">看看这一发，能为下一发改进什么。</small></div>`}
 function update(s,combat){const count=document.getElementById('cockpit-record-value'),detail=document.getElementById('cockpit-record-detail');if(!count||!detail)return;const row=s.active?s.logs.at(-1):null;count.textContent=s.active?`${s.logs.length} 发已记录 · ${s.installed&&s.assist?'瞄准辅助开启':'手动瞄准'}`:`击败 ${combat.kills} · 合金 ${combat.scrap}`;detail.textContent=row?`最近一发 ${Math.round(row.distance/18)} m · 偏差 ${row.residual.toFixed(1)}° · ${row.hit?'命中':'打偏'}`:'沿路探索，新的发现会记入旅途记录。'}
 function gallery(){return `<div class="visual-gallery"><span class="exo-tag">EXO / FIELD ARCHIVE</span><h2>远星画册</h2><button onclick="Exo.journal('regions')">地区图册 · 36 张风景与设定图 ↗</button><p>看看这片荒原、机甲与异兽的样子。这里收录了场景画面和美术设定。</p><div class="visual-gallery-grid">${[['assets/canyon-v2/canyon-hero.jpg','K–09 层岩峡谷','峡谷场景渲染'],['basalt-valley.webp','玄武岩荒原','探索区环境'],['stalker-valley.webp','机械猎脊兽','荒原上的机械猎手'],['stalker-reference.webp','装甲与关节','敌人造型参考'],['cockpit-reference.webp','EV–04 AEGIS 驾驶舱','驾驶舱视觉参考'],['orbital-ring.webp','断裂的中继环','轨道战争遗迹'],['expedition-hero.webp','最后的勘探机甲','远星协议']].map(([src,title,caption])=>`<figure><img src="${src.startsWith('assets/')?src:root+src}" loading="lazy" alt="${title}"><figcaption><b>${title}</b><span>${caption}</span></figcaption></figure>`).join('')}</div><button class="primary" onclick="closeModal()">继续探索</button></div>`}
 return {root,beats,begin,stop,finish,toggle,audio,sync,cockpit,update,gallery};
})();
if(typeof module!=='undefined')module.exports=ExoVisuals;
